update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing='11월 초', rd_timing='2월 초', deadlines_source_url='https://www.ou.edu/admissions/apply/freshman', deadlines_verified_at='2026-09-28', essay_req='기본 에세이 1개(250~650단어, 7개 주제 중 선택)와 장학금 심사용 짧은 보충 질문 2개(합쳐서 650단어 이내)를 내고, 전공에 따라 질문이 하나 더 있을 수 있어요.', essay_req_en='One required personal essay (250-650 words, choice of seven prompts) plus two required short supplemental scholarship questions (650 words or less combined), with a possible additional major-specific question.', essay_cycle='2026-27', essay_source_url='https://www.ou.edu/admissions/apply/freshman/essay' where id=164;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing='11월 초', rd_timing='1월 중순', deadlines_source_url='https://www.uoregon.edu/admissions/undergraduate/find-your-path/first-year-students', deadlines_verified_at='2026-09-28', essay_req='지원서의 다른 곳에서 알 수 없는 이야기를 쓰는 필수 에세이 1개(650단어 이내)를 내요. Clark Honors College에 지원하면 500단어 에세이가 하나 더 필요하고, 500단어 소속감 에세이는 선택이에요.', essay_req_en='One required essay (650 words or less) sharing information not found elsewhere in the application; Clark Honors College applicants write an additional 500-word essay, and a 500-word equity/belonging essay is optional.', essay_cycle='2026-27', essay_source_url='https://www.uoregon.edu/admissions/undergraduate/find-your-path/first-year-students' where id=165;
