update public.schools set test_policy='test-optional', ed_offered=true, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing='11월 초', ed2_timing=null, ea_timing='11월 초', rd_timing='2월 초', deadlines_source_url='https://miamioh.edu/admission-aid/apply/dates-deadlines/undergraduate-students.html', deadlines_verified_at='2026-09-28', essay_req='학교별 보충 에세이는 안내돼 있지 않아요. 국제학생이 Miami 자체 국제 지원서로 지원하면 에세이가 필요 없고, Common App으로 지원하면 Common App 기본 에세이를 내요.', essay_req_en='No Miami-specific supplemental essays are listed; international applicants using the Miami International Application need no essay, while the Common App route includes its personal essay.', essay_cycle='2026-27', essay_source_url='https://miamioh.edu/admission-aid/apply/international-students/' where id=177;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing='11월 초', rd_timing='3월 초', deadlines_source_url='https://www.jefferson.edu/admissions/undergraduate/first-year/apply.html', deadlines_verified_at='2026-09-28', essay_req='에세이(자기소개서)를 1개 내야 하고, 일부 전공은 전공별 보충 에세이를 추가로 요구해요(주제는 지원서에서 확인해요).', essay_req_en='An essay/personal statement is required; some programs additionally require a program-specific supplemental essay (prompts shown in the application).', essay_cycle='2026-27', essay_source_url='https://www.jefferson.edu/admissions/undergraduate/first-year/apply.html' where id=178;
