update public.schools set test_policy='test-free', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='11월 말', deadlines_source_url='https://www.csulb.edu/enrollment-services/key-dates-and-deadlines', deadlines_verified_at='2026-09-28', essay_req='에세이는 없어요. CSULB는 자기소개서·에세이·추천서를 입학 심사에 반영하지 않는다고 안내해요.', essay_req_en='No essays; CSULB states personal statements, essays and recommendation letters are not considered in admission (Cal State Apply collects academic history only).', essay_cycle='2026-27', essay_source_url='https://www.csulb.edu/admissions/first-time-first-year-student-application-process' where id=180;
