update public.schools set test_policy='test-optional', ed_offered=true, ed2_offered=true, ea_offered=true, rea_offered=false, ed_timing='11월 중순', ed2_timing='1월 중순', ea_timing='11월 중순', rd_timing='2월 초', deadlines_source_url='https://www.sju.edu/admission/undergraduate/first-year', deadlines_verified_at='2026-09-28', essay_req='Common App 주제로 쓰는 개인 에세이 1개를 내요(SJU 자체 지원서도 같아요). 학교별 보충 에세이는 안내되어 있지 않아요.', essay_req_en='One personal essay using a Common App prompt is required (also on SJU''s own application); no school-specific supplemental essay listed.', essay_cycle='2026-27', essay_source_url='https://www.sju.edu/admission/undergraduate/first-year' where id=182;
update public.schools set test_policy='test-free', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='11월 말', deadlines_source_url='https://admissions.sdsu.edu/first-years', deadlines_verified_at='2026-09-28', essay_req='에세이는 없어요. Cal State Apply에 과목·성적·활동 정보를 직접 입력하고, 그 정보로 합격을 결정해요.', essay_req_en='No essays; Cal State Apply collects self-reported coursework, grades and activity information only, and decisions are based on that information.', essay_cycle='2026-27', essay_source_url='https://admissions.sdsu.edu/first-years' where id=183;
update public.schools set test_policy='test-free', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='11월 말', deadlines_source_url='https://www.sjsu.edu/admissions/deadlines/index.php', deadlines_verified_at='2026-09-28', essay_req='에세이는 없어요. Cal State Apply에 학업 기록을 입력하는 방식이고, 입학 절차에 에세이나 자기소개서가 없어요.', essay_req_en='No essays; Cal State Apply collects academic history, and SJSU''s steps to admission list no essay or personal statement.', essay_cycle='2026-27', essay_source_url='https://www.sjsu.edu/admissions/freshman/want-to-apply/freshman-steps-to-admission/index.php' where id=184;
update public.schools set test_policy='test-optional', essay_req='대부분 전공은 필수 에세이가 없지만, 시험 점수 없이 지원하면 개인 에세이를 내는 게 권장되고 국제학생에게도 강하게 권장돼요. 6년제 약학(Pharm.D.)은 ''왜 St. John''s 약학인가'' 에세이(250단어)가 필수예요.', essay_req_en='No required essay for most programs; a personal essay is recommended for test-optional applicants and strongly encouraged for international applicants. The six-year Pharm.D. requires a 250-word essay on why Pharmacy at St. John''s.', essay_cycle='2026-27', essay_source_url='https://www.stjohns.edu/admission/undergraduate-admission/application-requirements' where id=185;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='6월 초', deadlines_source_url='https://www.uab.edu/admissions/apply/freshman/how-to-apply', deadlines_verified_at='2026-09-28', essay_req='에세이는 필요 없어요. 지원서와 전형료, 고등학교 성적표, (선택) SAT/ACT 점수만 내면 돼요.', essay_req_en='No essay required; UAB''s application steps are the application and fee, official transcript, and optional ACT/SAT scores.', essay_cycle='2026-27', essay_source_url='https://www.uab.edu/admissions/apply/freshman/how-to-apply' where id=186;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='5월 말', deadlines_source_url='https://uh.edu/undergraduate-admissions/apply/incoming-freshman/', deadlines_verified_at='2026-09-28', essay_req='모든 지원자가 짧은 입학 에세이 1개(Common App·ApplyTexas 주제 1·2·3·5번 중 선택)와 활동 이력(레쥬메)을 내야 해요. 제출 후에는 추가할 수 없어요.', essay_req_en='One short admissions essay is required of all applicants (choose Common App/ApplyTexas prompt 1, 2, 3 or 5), plus a resume/activities section; it cannot be added after submission.', essay_cycle='2026-27', essay_source_url='https://uh.edu/undergraduate-admissions/apply/incoming-freshman/' where id=187;
