update public.schools set test_policy='test-optional', ed_offered=true, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing='11월 중순', ed2_timing=null, ea_timing='11월 중순', rd_timing='롤링 (마감일 없음)', deadlines_source_url='https://admissions.scranton.edu/apply/freshman/freshman-deadlines.shtml', deadlines_verified_at='2026-09-28', essay_req='개인 에세이(Common App 기본 에세이)를 내야 하고, 학교 자체 보충 에세이는 안내되어 있지 않아요.', essay_req_en='A personal statement is required (Common App essay); no Scranton-specific supplemental essays were found.', essay_cycle='2026-27', essay_source_url='https://admissions.scranton.edu/apply/international/international-checklist.shtml' where id=189;
