update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing='12월 초', rd_timing='2월 중순', deadlines_source_url='https://admission.uky.edu/freshman', deadlines_verified_at='2026-09-28', essay_req='일반 지원에는 에세이가 없어요. 지원서(UK 자체 지원서나 Common App)·성적표·전형료만 내면 되고, 일부 선발 전공은 따로 절차가 있어요.', essay_req_en='No essay required for general admission; required materials are the application (UK Application or Common App), transcript, fee, and optional test scores. Some selective programs have separate processes.', essay_cycle='2026-27', essay_source_url='https://admission.uky.edu/freshman/admission-checklist' where id=194;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing='11월 초', rd_timing='2월 중순', deadlines_source_url='https://www.uml.edu/admissions/freshmen-applicants.aspx', deadlines_verified_at='2026-09-28', essay_req='개인 에세이 1개(250~650단어, Common App 주제나 학교 자체 주제 3개 중 선택)와 추천서 1통을 내요. 추가 보충 에세이는 없어요.', essay_req_en='One required personal essay of 250-650 words (a Common App prompt or one of UMass Lowell''s three prompts), plus one letter of recommendation; no additional supplemental essays.', essay_cycle='2026-27', essay_source_url='https://www.uml.edu/admissions/apply/' where id=195;
update public.schools set test_policy='test-optional', ed_offered=true, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing='11월 초', ed2_timing=null, ea_timing='12월 초', rd_timing='2월 초', deadlines_source_url='https://web.uri.edu/admission/apply/first-year/', deadlines_verified_at='2026-09-28', essay_req='Common App 기본 에세이를 내고, 보충 에세이는 Honors·간호·약학·Talent Development 지원자만 써요. 추천서는 1통(약학은 2통)이 필요해요.', essay_req_en='The Common App personal essay is required; supplemental essays are required only for Honors, Nursing, Pharmacy, and Talent Development applicants. One letter of recommendation (two for Pharmacy).', essay_cycle='2026-27', essay_source_url='https://web.uri.edu/admission/apply/first-year/' where id=196;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='2월 초', deadlines_source_url='https://www.cuny.edu/admissions/undergraduate/apply/', deadlines_verified_at='2026-09-28', essay_req='시티 칼리지는 CUNY 지원서에서 에세이를 요구하지 않아요(에세이는 바루크·헌터·퀸스 지원자만 해당돼요).', essay_req_en='No essay required for City College on the CUNY application (CUNY essays apply only to Baruch, Hunter and Queens).', essay_cycle='2026-27', essay_source_url='https://www.cuny.edu/admissions/undergraduate/apply/' where id=197;
update public.schools set test_policy='test-free', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='11월 말', deadlines_source_url='https://admissions.fullerton.edu/deadlines/', deadlines_verified_at='2026-09-28', essay_req='에세이는 없어요. Cal State Apply에 과목·성적 등 학업 기록만 입력하면 돼요.', essay_req_en='No essay required; Cal State Apply asks only for self-reported coursework, grades, and application details.', essay_cycle='2026-27', essay_source_url='https://admissions.fullerton.edu/prospective-students/first-year.html' where id=198;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing='11월 중순', rd_timing='1월 중순', deadlines_source_url='https://www.duq.edu/admission-and-aid/how-to-apply/undergraduate/application-options-important-dates.php', deadlines_verified_at='2026-09-28', essay_req='대부분 전공은 에세이가 선택이에요. 보건 계열 지원자는 ''나만의 특별한 점·그 전공을 고른 이유·듀케인이 목표에 어떻게 도움이 될지''를 담은 개인 에세이를 꼭 내야 해요. 국제학생은 같은 질문에 답하는 300단어 이상 에세이를 내라고 안내돼 있어요.', essay_req_en='Essays are optional for most majors; health-professions applicants must write a personal essay (why this health field, what makes you unique, how Duquesne helps your goals). International first-year applicants are asked for a personal statement of at least 300 words on the same questions.', essay_cycle='2026-27', essay_source_url='https://www.duq.edu/admission-and-aid/how-to-apply/undergraduate/requirements.php' where id=199;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='롤링 (마감일 없음, 12월 초 장학금 우선 검토)', deadlines_source_url='https://www.k-state.edu/admissions/undergrad/manhattan/apply/deadlines.html', deadlines_verified_at='2026-09-28', essay_req='에세이는 없어요. 30분 정도 걸리는 지원서와 성적표, (선택) 시험 점수만 내면 돼요.', essay_req_en='No essay required; the freshman application (about 30 minutes) asks only for application details, transcripts and optional test scores.', essay_cycle='2026-27', essay_source_url='https://www.k-state.edu/admissions/undergrad/manhattan/apply/incoming-freshmen/guide.html' where id=200;
update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=true, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing='12월 초', rd_timing='3월 초', deadlines_source_url='https://www.montclair.edu/admissions-aid/how-apply-montclair-state-university/how-apply-montclairs-undergraduate-programs', deadlines_verified_at='2026-09-28', essay_req='개인 에세이 1개를 내요(''왜 몬클레어인지, 학업 강점·관심사, 성적에 영향을 준 상황''). 에세이 대신 학교 과제로 채점받은 글을 내도 돼요. 예술·간호 전공은 전공별 질문이 따로 있고, 단어 제한은 안내가 없어요.', essay_req_en='One required personal statement for first-year applicants (why Montclair, academic strengths and interests, and any circumstances affecting your record); a graded class writing sample may be submitted instead. Arts and Nursing applicants answer major-specific prompts; no word limit is stated.', essay_cycle='2026-27', essay_source_url='https://www.montclair.edu/admissions-aid/how-apply-montclair-state-university/how-apply-montclairs-undergraduate-programs/essay-prompts' where id=201;
