update public.schools set test_policy='test-optional', ed_offered=false, ed2_offered=false, ea_offered=false, rea_offered=false, ed_timing=null, ed2_timing=null, ea_timing=null, rd_timing='1월 중순', deadlines_source_url='https://admissions.vcu.edu/apply-to-vcu/deadlines/', deadlines_verified_at='2026-09-28', essay_req='2027년 지원자 모두 Common App으로 에세이를 내야 해요. VCU만의 추가 질문이나 단어 제한은 안내가 없어요.', essay_req_en='An essay is required of all 2027 applicants and must be submitted with the Common App; no VCU-specific supplemental prompt or word limit is listed.', essay_cycle='2026-27', essay_source_url='https://admissions.vcu.edu/apply-to-vcu/undergraduate/first-year/first-year-requirements/' where id=207;
